/*
=============================================================
Banking Transaction Analytics | Create database and load data
=============================================================
Creates 'BankingAnalyticsDB' (SQL Server) with three tables in the 'Banking' schema:
    Banking.Customers      (600 customers)
    Banking.Accounts       (712 accounts)
    Banking.Transactions   (16132 transactions, including labelled fraud)

All names and data are fictional (generated with generate_seed_data.py, seed 2026).
Amounts are in SAR. The data covers January to December 2025.

WARNING: running this script drops the existing 'BankingAnalyticsDB' database.
*/

USE master;
GO

IF EXISTS (SELECT 1 FROM sys.databases WHERE name = 'BankingAnalyticsDB')
BEGIN
    ALTER DATABASE BankingAnalyticsDB SET SINGLE_USER WITH ROLLBACK IMMEDIATE;
    DROP DATABASE BankingAnalyticsDB;
END;
GO

CREATE DATABASE BankingAnalyticsDB;
GO

USE BankingAnalyticsDB;
GO

EXEC sys.sp_executesql N'CREATE SCHEMA Banking;';
GO

CREATE TABLE Banking.Customers (
    CustomerID       INT NOT NULL,
    FirstName        VARCHAR(50),
    LastName         VARCHAR(50),
    City             VARCHAR(50),
    Country          CHAR(2),
    RegistrationDate DATE,
    CONSTRAINT PK_customers PRIMARY KEY (CustomerID)
);
GO

CREATE TABLE Banking.Accounts (
    AccountID   INT NOT NULL,
    CustomerID  INT NOT NULL,
    AccountType VARCHAR(20),          -- Checking / Savings
    OpenDate    DATE,
    Status      VARCHAR(20),
    CONSTRAINT PK_accounts PRIMARY KEY (AccountID),
    CONSTRAINT FK_accounts_customers FOREIGN KEY (CustomerID) REFERENCES Banking.Customers (CustomerID)
);
GO

CREATE TABLE Banking.Transactions (
    TxnID            INT NOT NULL,
    AccountID        INT NOT NULL,
    TxnDate          DATETIME2(0) NOT NULL,
    Amount           DECIMAL(12,2) NOT NULL,   -- always positive, TxnType gives the direction
    TxnType          VARCHAR(20),              -- Purchase / Withdrawal / Deposit / Transfer
    Channel          VARCHAR(20),              -- POS / ATM / Online / Branch
    Country          CHAR(2),                  -- where the transaction happened
    MerchantCategory VARCHAR(30),
    CONSTRAINT PK_transactions PRIMARY KEY (TxnID),
    CONSTRAINT FK_transactions_accounts FOREIGN KEY (AccountID) REFERENCES Banking.Accounts (AccountID)
);
GO

CREATE INDEX IX_transactions_account_date ON Banking.Transactions (AccountID, TxnDate);
GO

